64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
73	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
74	     * addresses are lower-cased before being stored.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /** An owner's postcode, when supplied, must be exactly four digits. */
80	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
81	
82	    /**
83	     * Disposable e-mail domains an owner may not sign up with. An email whose domain (the part after
84	     * the '@', compared case-insensitively) is on this blocklist is rejected with a 400.
85	     */
86	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
87	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
88	
89	    /**
90	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
91	     * named logger keeps them addressable independently of the class's diagnostic logging.
92	     */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * Maximum number of owners a single city may contain. A create that would take the owner's city
97	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
98	     */
99	    private static final int CITY_OWNER_LIMIT = 50;
100	
101	    /**
102	     * Maximum number of owners that may be registered on a single day. A create that would take the
103	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
104	     * have already been created that day - is rejected with a 429.
105	     */
106	    private static final int DAILY_OWNER_LIMIT = 100;
107	
108	    /**
109	     * Number of owners that must already have been created for a given day before the create
110	     * response flags a bulk sign-up. When more than this many owners already share a
111	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
112	     */
113	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
114	
115	    /**
116	     * Fixed list of public holidays. A registration date that lands on one of these dates is treated
117	     * like a weekend and rolled forward to the next non-holiday business day.
118	     */
119	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
120	        LocalDate.of(2026, 1, 1),
121	        LocalDate.of(2026, 1, 26),
122	        LocalDate.of(2026, 4, 25),
123	        LocalDate.of(2026, 12, 25),
124	        LocalDate.of(2026, 12, 28));
125	
126	    private final ClinicService clinicService;
127	
128	    private final OwnerMapper ownerMapper;
129	
130	    private final PetMapper petMapper;
131	
132	    private final VisitMapper visitMapper;
133	
134	    public OwnerRestControllerV1(ClinicService clinicService,
135	                                 OwnerMapper ownerMapper,
136	                                 PetMapper petMapper,
137	                                 VisitMapper visitMapper) {
138	        this.clinicService = clinicService;
139	        this.ownerMapper = ownerMapper;
140	        this.petMapper = petMapper;
141	        this.visitMapper = visitMapper;
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
147	        Collection<Owner> owners;
148	        if (lastName != null) {
149	            owners = this.clinicService.findOwnerByLastName(lastName);
150	        } else {
151	            owners = this.clinicService.findAllOwners();
152	        }
153	        if (owners.isEmpty()) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
167	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
168	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
169	    }
170	
171	    /**
172	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
173	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
174	     * owner sign-ups.
175	     *
176	     * @param registrationDate the day to inspect, or {@code null}
177	     * @return {@code true} when more than the threshold of owners are registered on that day
178	     */
179	    private boolean isBulkSignupDay(LocalDate registrationDate) {
180	        return registrationDate != null
181	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
187	        Owner owner = buildOwnerToCreate(ownerFieldsDto);
188	        boolean bulkSignupWarning = enforceCreateLimits(owner) > BULK_SIGNUP_WARNING_THRESHOLD;
189	        finalizeOwnerForCreate(owner);
190	        this.clinicService.saveOwner(owner);
191	        return createdOwnerResponse(owner, bulkSignupWarning);
192	    }
193	
194	    /**
195	     * Resolves, validates and maps a create request into a fully-normalized {@link Owner} that is
196	     * ready to persist except for the derived fields assigned by {@link #finalizeOwnerForCreate}. The
197	     * submitted address is canonicalized, the required fields and the optional postcode and
198	     * registration date are validated, and the mapped owner's telephone and email are normalized. The
199	     * registration date is defaulted to the server date when absent and rolled forward to a business
200	     * day. The household id and identity key are derived; a create that would join an already-populated
201	     * household is rejected unless it opts in with {@code sharesHousehold}, and otherwise a soft-match
202	     * duplicate is flagged.
203	     *
204	     * @param ownerFieldsDto the submitted owner fields
205	     * @return the normalized owner, not yet persisted
206	     */
207	    private Owner buildOwnerToCreate(OwnerFieldsDto ownerFieldsDto) {
208	        resolveAddressFields(ownerFieldsDto);
209	        validateRequiredFields(ownerFieldsDto);
210	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
211	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
212	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
213	        owner.setEmail(normalizeEmail(owner.getEmail()));
214	        validateRegistrationDate(owner.getRegistrationDate());
215	        if (owner.getRegistrationDate() == null) {
216	            owner.setRegistrationDate(LocalDate.now());
217	        }
218	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
219	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
220	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
221	        owner.setIdentityKey(buildIdentityKey(owner));
222	        if (!sharesHousehold) {
223	            rejectHouseholdDuplicate(owner.getHouseholdId());
224	        }
225	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
226	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
227	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
228	        return owner;
229	    }
230	
231	    /**
232	     * Enforces the per-city and per-day capacity limits for a new owner, in that order. A create that
233	     * would take the owner's city beyond {@link #CITY_OWNER_LIMIT} owners is rejected with a 409, and
234	     * one that would take the owner's registration date beyond {@link #DAILY_OWNER_LIMIT} owners is
235	     * rejected with a 429. The returned count is the number of owners already sharing the owner's
236	     * registration date, measured before it is saved, which the caller uses to decide the response's
237	     * {@code bulkSignupWarning}.
238	     *
239	     * @param owner the normalized owner about to be created
240	     * @return the number of owners already registered on the owner's registration date
241	     */
242	    private long enforceCreateLimits(Owner owner) {
243	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
244	            throw new OwnerCityFullException(owner.getCity());
245	        }
246	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
247	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
248	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
249	        }
250	        return ownersRegisteredOnDay;
251	    }
252	
253	    /**
254	     * Assigns the derived fields that only apply once the owner has cleared the create checks: its
255	     * de-duplicated customer code, the number of existing namesakes, and the household size once the
256	     * new owner is added.
257	     *
258	     * @param owner the normalized owner about to be created
259	     */
260	    private void finalizeOwnerForCreate(Owner owner) {
261	        owner.setCustomerCode(buildCustomerCode(owner));
262	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
263	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
264	    }
265	
266	    /**
267	     * Builds the {@code 201 Created} response for a freshly persisted owner: maps it to a DTO, emits
268	     * the audit record, sets the {@code bulkSignupWarning} the caller computed from the pre-save daily
269	     * count, and adds the {@code Location} header pointing at the new owner.
270	     *
271	     * @param owner the owner that has just been saved, with its generated id populated
272	     * @param bulkSignupWarning whether the response should flag an unusually high same-day sign-up volume
273	     * @return the created-owner response
274	     */
275	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner, boolean bulkSignupWarning) {
276	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
277	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
278	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
279	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
280	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
281	        HttpHeaders headers = new HttpHeaders();
282	        headers.setLocation(UriComponentsBuilder.newInstance()
283	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
284	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
285	    }
286	
287	    /**
288	     * Canonicalizes the submitted address fields into the form that is validated, stored and
289	     * returned, before any required-field check or mapping runs. This is the single place a create
290	     * request's address input is resolved.
291	     *
292	     * <p>The structured fields are preferred over the flat input for backward compatibility: when a
293	     * non-blank {@code addressLine1} is supplied, {@code addressLine1} and the optional
294	     * {@code addressLine2} are {@link AddressNormalizer#normalize normalized} in place and the flat
295	     * {@code address} is set to the composed value - the normalized {@code addressLine1}, with a
296	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
297	     * present. When no structured line is supplied the flat {@code address} is normalized in place,
298	     * exactly as before. Either way everything downstream - the required-field check, the mapping onto
299	     * {@link Owner} and the response - sees the canonical address rather than the raw input. A value
300	     * that is blank only after normalization is left blank here and rejected later by
301	     * {@link #validateRequiredFields}.
302	     *
303	     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
304	     */
305	    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
306	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
307	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
308	        if (!line1.isEmpty()) {
309	            ownerFieldsDto.setAddressLine1(line1);
310	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
311	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
312	        }
313	        else {
314	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
315	        }
316	    }
317	
318	    /**
319	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
320	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
321	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
322	     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
323	     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
324	     * normalization is still rejected.
325	     *
326	     * @param ownerFieldsDto the submitted owner fields
327	     */
328	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
329	        List<String> missingFields = new ArrayList<>();
330	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
331	            missingFields.add("firstName");
332	        }
333	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
334	            missingFields.add("lastName");
335	        }
336	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
337	            missingFields.add("address");
338	        }
339	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
340	            missingFields.add("city");
341	        }
342	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
343	            missingFields.add("telephone");
344	        }
345	        if (!missingFields.isEmpty()) {
346	            throw new MissingOwnerFieldsException(missingFields);
347	        }
348	    }
349	
350	    /**
351	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
352	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
353	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
354	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
355	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
356	     * whose {@code errors} array lists {@code postcode}.
357	     *
358	     * @param postcode the submitted postcode, or {@code null} when none was supplied
359	     * @param city the owner's city, whose region determines the acceptable postcode range
360	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
361	     */
362	    private void validatePostcode(String postcode, String city) {
363	        if (!StringUtils.hasText(postcode)) {
364	            return;
365	        }
366	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
367	            throw new InvalidOwnerFieldsException(List.of("postcode"));
368	        }
369	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
370	            throw new InvalidOwnerFieldsException(List.of("postcode"));
371	        }
372	    }
373	
374	    /**
375	     * Validates an owner's optional registration date. Registration date is optional, so a missing
376	     * value is accepted (the create later defaults it to the server date). When a value is supplied
377	     * it may not lie in the future: a date later than the server's current date is rejected with a
378	     * 400 whose {@code errors} array lists {@code registrationDate}.
379	     *
380	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
381	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
382	     */
383	    private void validateRegistrationDate(LocalDate registrationDate) {
384	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
385	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
386	        }
387	    }
388	
389	    /**
390	     * Rejects a submitted owner that would join a household which already has a member. Because the
391	     * {@code householdId} is derived deterministically from the owner's last name and postcode, any
392	     * existing owner sharing that id is the same household, so a second such owner is reported to the
393	     * client as a 409 Conflict. A request may knowingly bypass this block by opting in with
394	     * {@code sharesHousehold}, in which case this check is not performed.
395	     *
396	     * @param householdId the derived household identifier of the owner about to be created
397	     */
398	    private void rejectHouseholdDuplicate(String householdId) {
399	        boolean duplicate = this.clinicService.findAllOwners().stream()
400	            .filter(existing -> !existing.isDeleted())
401	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
402	        if (duplicate) {
403	            throw new DuplicateOwnerIdentityException(householdId);
404	        }
405	    }
406	
407	    /**
408	     * Derives the owner's {@code identityKey}, formatted
409	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
410	     * and email have already been normalized. The household segment always carries the owner's
411	     * deterministic {@code householdId}, since owners with the same last name and postcode belong to
412	     * the same household automatically.
413	     *
414	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
415	     * @return the derived identity key
416	     */
417	    private String buildIdentityKey(Owner owner) {
418	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
419	        return owner.getTelephone() + "|" + email + "|" + owner.getHouseholdId();
420	    }
421	
422	    /**
423	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner that
424	     * shares an existing owner's {@code lastName} (case-insensitively) and {@code postcode} while
425	     * having a different normalized {@code telephone}. Such an owner is still created, but is flagged
426	     * as a possible duplicate of the matching owner. This is only consulted for owners that did not
427	     * opt into a shared household: an owner that declares {@code sharesHousehold} is a known household
428	     * member, not a suspected duplicate, so it is never flagged. The comparison only applies when a
429	     * postcode was supplied, since both owners must share one; when several existing owners match, the
430	     * earliest (lowest id) is used.
431	     *
432	     * @param owner the normalized owner about to be created, with its telephone already normalized
433	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
434	     */
435	    private Integer findPossibleDuplicate(Owner owner) {
436	        if (!StringUtils.hasText(owner.getPostcode())) {
437	            return null;
438	        }
439	        return this.clinicService.findAllOwners().stream()
440	            .filter(existing -> !existing.isDeleted())
441	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
442	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
443	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
444	            .map(Owner::getId)
445	            .filter(id -> id != null)
446	            .min(Integer::compareTo)
447	            .orElse(null);
448	    }
449	
450	    /**
451	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
452	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
453	     * address; the accepted value is lower-cased before it is stored and returned.
454	     *
455	     * @param email the raw email value submitted by the client, or {@code null}
456	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
457	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
458	     */
459	    private String normalizeEmail(String email) {
460	        if (!StringUtils.hasText(email)) {
461	            return email;
462	        }
463	        if (!EMAIL_PATTERN.matcher(email).matches()) {
464	            throw new InvalidOwnerFieldsException(List.of("email"));
465	        }
466	        String normalized = email.toLowerCase();
467	        String domain = normalized.substring(normalized.indexOf('@') + 1);
468	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
469	            throw new InvalidOwnerFieldsException(List.of("email"));
470	        }
471	        return normalized;
472	    }
473	
474	    /**
475	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
476	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
477	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
478	     * When the composed code collides with an existing owner's customer code, it is de-duplicated by
479	     * appending {@code -<n>} with the smallest {@code n} of two or more that makes it unique.
480	     *
481	     * @param owner the normalized owner about to be created
482	     * @return the assigned, de-duplicated customer code
483	     */
484	    private String buildCustomerCode(Owner owner) {
485	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
486	        String code = CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
487	        return deduplicateCustomerCode(code);
488	    }
489	
490	    /**
491	     * De-duplicates a freshly composed customer code against the codes of all existing owners. When
492	     * the code is already unique it is returned unchanged; otherwise {@code -<n>} is appended, using
493	     * the smallest {@code n} of two or more that yields a code no existing owner holds.
494	     *
495	     * @param code the composed customer code, before de-duplication
496	     * @return the same code when unique, otherwise the code with the smallest available {@code -<n>} suffix
497	     */
498	    private String deduplicateCustomerCode(String code) {
499	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
500	            .map(Owner::getCustomerCode)
501	            .filter(existing -> existing != null)
502	            .collect(Collectors.toSet());
503	        if (!existingCodes.contains(code)) {
504	            return code;
505	        }
506	        int suffix = 2;
507	        while (existingCodes.contains(code + "-" + suffix)) {
508	            suffix++;
509	        }
510	        return code + "-" + suffix;
511	    }
512	
513	    /**
514	     * Counts how many owners already exist that share the supplied first and last name, compared
515	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
516	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
517	     *
518	     * @param firstName the submitted owner's first name
519	     * @param lastName the submitted owner's last name
520	     * @return the number of existing owners with the same first and last name, ignoring case
521	     */
522	    private int countNamesakes(String firstName, String lastName) {
523	        return (int) this.clinicService.findAllOwners().stream()
524	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
525	                && lastName.equalsIgnoreCase(existing.getLastName()))
526	            .count();
527	    }
528	
529	    /**
530	     * Counts how many existing owners already belong to the supplied household, identified by its
531	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
532	     * owner is added (this count plus one).
533	     *
534	     * @param householdId the normalized household identifier of the owner being created
535	     * @return the number of existing owners already sharing that {@code householdId}
536	     */
537	    private int countHouseholdMembers(String householdId) {
538	        return (int) this.clinicService.findAllOwners().stream()
539	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
540	            .count();
541	    }
542	
543	    /**
544	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
545	     * enforce the per-city capacity limit when a new owner is created.
546	     *
547	     * @param city the submitted owner's city
548	     * @return the number of existing owners in that city, ignoring case
549	     */
550	    private long countOwnersInCity(String city) {
551	        return this.clinicService.findAllOwners().stream()
552	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
553	            .count();
554	    }
555	
556	    /**
557	     * Counts how many owners have already been created on the supplied registration date. Used to
558	     * enforce the per-day capacity limit when a new owner is created.
559	     *
560	     * @param registrationDate the registration date of the owner being created
561	     * @return the number of existing owners already registered on that date
562	     */
563	    /**
564	     * Rolls a registration date forward to a business day. A registration date must fall on a
565	     * business day, so when the supplied or defaulted date lands on a Saturday, Sunday or a listed
566	     * public holiday it is moved forward to the next non-holiday weekday; a plain weekday is
567	     * returned unchanged. Every value derived from the registration date (such as the membership
568	     * number's year segment) and the daily create-limit therefore use the adjusted date.
569	     *
570	     * @param date the effective registration date, whether supplied or defaulted to the server date
571	     * @return the same date when it is a business day, otherwise the next non-holiday weekday
572	     */
573	    private LocalDate toBusinessDay(LocalDate date) {
574	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
575	            date = date.plusDays(1);
576	        }
577	        return date;
578	    }
579	
580	    private boolean isWeekend(LocalDate date) {
581	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
582	    }
583	
584	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
585	        return this.clinicService.findAllOwners().stream()
586	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
587	            .count();
588	    }
589	
590	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
591	    @Override
592	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
593	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
594	        if (currentOwner == null) {
595	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
596	        }
597	        currentOwner.setAddress(ownerFieldsDto.getAddress());
598	        currentOwner.setCity(ownerFieldsDto.getCity());
599	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
600	        currentOwner.setLastName(ownerFieldsDto.getLastName());
601	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
602	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
603	        this.clinicService.saveOwner(currentOwner);
604	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
605	    }
606	
607	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
608	    @Transactional
609	    @Override
610	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
611	        Owner owner = this.clinicService.findOwnerById(ownerId);
612	        if (owner == null) {
613	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
614	        }
615	        owner.setDeleted(true);
616	        this.clinicService.saveOwner(owner);
617	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
618	    }
619	
620	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
621	    @Override
622	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
623	        Owner owner = this.clinicService.findOwnerById(ownerId);
624	        if (owner == null) {
625	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
626	        }
627	        HttpHeaders headers = new HttpHeaders();
628	        Pet pet = petMapper.toPet(petFieldsDto);
629	        owner.setId(ownerId);
630	        pet.setOwner(owner);
631	        pet.getType().setName(null);
632	        this.clinicService.savePet(pet);
633	        PetDto petDto = petMapper.toPetDto(pet);
634	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
635	            .buildAndExpand(pet.getId()).toUri());
636	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
637	    }
638	
639	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
640	    @Override
641	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
642	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
643	        if (currentOwner != null) {
644	            Pet currentPet = this.clinicService.findPetById(petId);
645	            if (currentPet != null) {
646	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
647	                currentPet.setName(petFieldsDto.getName());
648	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
649	                this.clinicService.savePet(currentPet);
650	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
651	            }
652	        }
653	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
654	    }
655	
656	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
657	    @Override
658	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
659	        HttpHeaders headers = new HttpHeaders();
660	        Visit visit = visitMapper.toVisit(visitFieldsDto);
661	        Pet pet = new Pet();
662	        pet.setId(petId);
663	        visit.setPet(pet);
664	        this.clinicService.saveVisit(visit);
665	        VisitDto visitDto = visitMapper.toVisitDto(visit);
666	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
667	            .buildAndExpand(visit.getId()).toUri());
668	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
669	    }
670	
671	
672	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
673	    @Override
674	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
675	        Owner owner = this.clinicService.findOwnerById(ownerId);
676	        if (owner != null) {
677	            Pet pet = owner.getPet(petId);
678	            if (pet != null) {
679	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
680	            }
681	        }
682	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
683	    }
684	}
